/usr/bin/bash -lc "PYTHONPATH=source python - <<'PY'
import itertools
import numpy as np
from deepmd.dpmodel.utils import GraphLayout, build_neighbor_graph
rng=np.random.default_rng(12)
for case in range(10):
    while True:
        cell=rng.normal(size=(3,3))*2
        if abs(np.linalg.det(cell))>.8:
            break
    coord=rng.normal(size=(1,3,3))*3
    cutoff=float(rng.uniform(.2,1.5))
    graph=build_neighbor_graph(coord,np.zeros((1,3),int),cell[None],cutoff,GraphLayout(min_edges=0))
    actual={(int(s),int(d),tuple(np.round(v,9))) for s,d,v in zip(graph.edge_index[0],graph.edge_index[1],graph.edge_vec)}
    inv=np.linalg.inv(cell)
    wrapped=np.mod(coord[0]@inv,1)@cell
    base=np.ceil(cutoff*np.linalg.norm(inv,axis=0)).astype(int)+2
    expected=set()
    for d in range(3):
        for shift in itertools.product(*(range(-int(x),int(x)+1) for x in base)):
            for s in range(3):
                if s==d and shift==(0,0,0):
                    continue
                vec=wrapped[s]+np.asarray(shift)@cell-wrapped[d]
                distance=np.linalg.norm(vec)
                if 0.0 < distance <= cutoff:
                    expected.add((s,d,tuple(np.round(vec,9))))
    assert actual == expected, (case, actual "'^ expected)
print('"'triclinic-bruteforce-ok')
PY"

